from __future__ import annotations

from mcp.server.fastmcp import FastMCP

from .service import BridgeService

mcp = FastMCP(
    "Zotero Research Bridge",
    instructions=(
        "Read-only access to the user's Zotero research library. For substantive sport-science questions, "
        "build a Zotero-first evidence pack before answering. Return bounded page-located evidence, label "
        "external fallback sources explicitly, and never represent a Reference Stub as a reviewed Paper Brief. "
        "SecondBrain Queue is the priority lane; promotion eligibility is controlled by promotion_scope."
    ),
)


@mcp.tool()
def zotero_health() -> dict:
    """Check read-only permissions, Zotero APIs, index freshness, queue, and SecondBrain."""
    with BridgeService.from_environment() as bridge:
        return bridge.health()


@mcp.tool()
def sync_zotero_library(
    force_full: bool = False,
    include_fulltext: bool = False,
    max_fulltext: int | None = None,
) -> dict:
    """Incrementally synchronize Zotero metadata and optionally indexed full text."""
    with BridgeService.from_environment() as bridge:
        return bridge.sync(
            force_full=force_full,
            include_fulltext=include_fulltext,
            max_fulltext=max_fulltext,
        )


@mcp.tool()
def search_papers(query: str, limit: int = 10) -> list[dict]:
    """Search Zotero metadata and cached full text; returns bounded provenance-rich results."""
    with BridgeService.from_environment() as bridge:
        return bridge.search(query, limit=limit)


@mcp.tool()
def get_paper(item_key: str) -> dict:
    """Get one paper's metadata, attachments, queue membership, and promotion record."""
    with BridgeService.from_environment() as bridge:
        return bridge.get_paper(item_key)


@mcp.tool()
def search_paper_evidence(item_key: str, query: str, limit: int = 5) -> list[dict]:
    """Search one paper and return short evidence snippets with PDF page locators."""
    with BridgeService.from_environment() as bridge:
        bridge.require_production_key()
        return bridge.evidence_search(item_key, query, limit=limit)

